	@Test
	void frozenBatchValidatesTheOriginalSerializableReadBoundary() throws Exception {
		try (MemorySailStore store = new MemorySailStore(false);
				SailSource backing = store.getExplicitSailSource();
				SailSource branch = backing.fork()) {
			Statement observed = statement("frozen-serializable-observation");
			try (SailDataset dataset = branch.dataset(IsolationLevels.SERIALIZABLE);
					CloseableIteration<? extends Statement> statements = dataset.getStatements(observed.getSubject(),
							observed.getPredicate(), observed.getObject(), observed.getContext())) {
				assertFalse(statements.hasNext(), "the branch establishes an actual negative observation");
			}

			try (SailSink competitor = backing.sink(IsolationLevels.NONE)) {
				competitor.prepare();
				competitor.approve(observed);
				competitor.flush();
			}
			try (SailDataset current = backing.dataset(IsolationLevels.NONE);
					CloseableIteration<? extends Statement> statements = current.getStatements(observed.getSubject(),
							observed.getPredicate(), observed.getObject(), observed.getContext())) {
				assertTrue(statements.hasNext(), "the backing source publishes Y before the frozen batch flushes");
			}

			SailSource.FlushBatch batch = branch.freezeForFlush();
			try {
				assertThrows(SailConflictException.class, batch::flush,
						"a fresh terminal sink must preserve the branch's original serializable read boundary");
			} finally {
				batch.close();
			}
		}
	}

