	@Test
	void preparedSameSnapshotFromUnrelatedOwnerIsNotExcludedAsFrozenOwnFlush() throws Exception {
		try (MemorySailStore store = new MemorySailStore(false);
				SailSource backing = store.getExplicitSailSource();
				SailSource branch = backing.fork()) {
			Statement observed = statement("same-snapshot-unrelated-observation");
			Statement branchWrite = statement("same-snapshot-branch-write");
			Statement unrelatedWrite = statement("same-snapshot-unrelated-write");
			Statement laterWrite = statement("same-snapshot-later-write");
			try (SailDataset dataset = branch.dataset(IsolationLevels.SERIALIZABLE);
					CloseableIteration<? extends Statement> statements = dataset.getStatements(observed.getSubject(),
							observed.getPredicate(), observed.getObject(), observed.getContext())) {
				assertFalse(statements.hasNext(), "the branch observes Y absent at native snapshot zero");
			}

			SailSink unrelated = backing.sink(IsolationLevels.NONE);
			SailSource.FlushBatch batch = null;
			try {
				unrelated.prepare();
				try (SailSink sink = branch.sink(IsolationLevels.NONE)) {
					sink.approve(branchWrite);
					sink.flush();
				}
				batch = branch.freezeForFlush();
				SailSource.FlushBatch retainedBatch = batch;
				assertThrows(SailConflictException.class, () -> {
					retainedBatch.flush();
					retainedBatch.unFreezeAndDiscardFlushed();
					unrelated.approve(unrelatedWrite);
					unrelated.flush();
					assertTrue(contains(backing, unrelatedWrite),
							"the unrelated sink publishes Y at its already-reserved native snapshot");
					unrelated.close();
					try (SailSink sink = branch.sink(IsolationLevels.NONE)) {
						sink.approve(laterWrite);
						sink.flush();
					}
					branch.prepare();
				}, "equal snapshot numbers from a different prepared owner are a real conflict");
			} finally {
				if (batch != null) {
					batch.close();
				}
				unrelated.close();
			}
		}
	}

