	@Test
	void failedChildStagingCannotReleaseAppliedUnacknowledgedMemoryParent() throws Exception {
		try (MemorySailStore store = new MemorySailStore(false);
				SailSource backing = store.getExplicitSailSource();
				SailSource parent = backing.fork();
				SailSource child = parent.fork();
				SailSource laterOwner = backing.fork()) {
			Statement parentObservation = statement("memory-parent-frozen-negative-read");
			try (SailDataset dataset = parent.dataset(IsolationLevels.SERIALIZABLE);
					CloseableIteration<? extends Statement> statements = dataset.getStatements(
							parentObservation.getSubject(), parentObservation.getPredicate(),
							parentObservation.getObject(), parentObservation.getContext())) {
				assertFalse(statements.hasNext(), "the parent retains a native SERIALIZABLE read boundary");
			}
			write(parent, "memory-parent-prefix");
			SailSource.FlushBatch parentBatch = parent.freezeForFlush();
			SailSource.FlushBatch childBatch = null;
			SailSource.FlushBatch laterBatch = null;
			try {
				parentBatch.flush();
				write(child, "memory-child-suffix");
				childBatch = child.freezeForFlush();
				assertThrows(IllegalStateException.class, childBatch::flush,
						"a child cannot enlist a backing branch already frozen by its unacknowledged parent batch");
				childBatch.close();
				childBatch = null;

				assertThrows(SailConflictException.class, () -> publish(backing, statement("writer-before-parent-ack")),
						"cancelling the failed child must preserve the parent's native exclusion");
				assertDoesNotThrow(parentBatch::flush, "the parent batch remains replayable after child cancellation");
				parentBatch.unFreezeAndDiscardFlushed();
				parentBatch.close();

				Statement laterObservation = statement("memory-later-owner-negative-read");
				try (SailDataset dataset = laterOwner.dataset(IsolationLevels.SERIALIZABLE);
						CloseableIteration<? extends Statement> statements = dataset.getStatements(
								laterObservation.getSubject(), laterObservation.getPredicate(),
								laterObservation.getObject(), laterObservation.getContext())) {
					assertFalse(statements.hasNext(), "the later owner retains its own native read boundary");
				}
				write(laterOwner, "memory-later-owner");
				laterBatch = laterOwner.freezeForFlush();
				laterBatch.flush();
				parentBatch.close();
				assertThrows(SailConflictException.class, () -> publish(backing, statement("writer-before-later-ack")),
						"re-closing the acknowledged parent must not release a later owner's exclusion");
				laterBatch.unFreezeAndDiscardFlushed();
				laterBatch.close();
				laterBatch = null;

				assertDoesNotThrow(() -> publish(backing, statement("writer-after-later-ack")),
						"acknowledgement releases the current owner's native exclusion exactly once");
			} finally {
				if (childBatch != null) {
					childBatch.close();
				}
				if (laterBatch != null) {
					laterBatch.close();
				}
				parentBatch.close();
			}
		}
	}

	@Test
	void crossThreadPreparedMemoryCarrierRejectsFrozenReplayPromptly() throws Exception {
		try (MemorySailStore store = new MemorySailStore(false);
				SailSource backing = store.getExplicitSailSource();
				SailSource branch = backing.fork()) {
			write(branch, "cross-thread-prepared-carrier");
			branch.prepare();
			AtomicReference<SailSource.FlushBatch> batchReference = new AtomicReference<>();
			AtomicReference<Throwable> failureReference = new AtomicReference<>();
			ExecutorService executor = Executors.newSingleThreadExecutor();
			try {
				Future<?> flush = executor.submit(() -> {
					SailSource.FlushBatch batch = branch.freezeForFlush();
					batchReference.set(batch);
					try {
						batch.flush();
					} catch (Throwable failure) {
						failureReference.set(failure);
					}
				});
				try {
					flush.get(5, TimeUnit.SECONDS);
				} catch (TimeoutException timeout) {
					executor.shutdownNow();
					assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS),
							"the interrupted frozen-flush worker must actually terminate");
					throw new AssertionError("cross-thread native preparation must fail promptly", timeout);
				}
				executor.shutdown();
				assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS),
						"the frozen-flush worker must actually terminate");
				assertTrue(failureReference.get() instanceof SailConflictException,
						"a native carrier prepared on another thread is a conflict, not a wait");
			} finally {
				executor.shutdownNow();
				assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS),
						"the frozen-flush worker terminates before owner-thread cleanup");
				SailSource.FlushBatch batch = batchReference.get();
				if (batch != null) {
					batch.close();
				}
			}
		}
	}

	private static void flushAndAcknowledge(SailSource branch) {
		SailSource.FlushBatch batch = branch.freezeForFlush();
		try {
			batch.flush();
			batch.unFreezeAndDiscardFlushed();
		} finally {
			batch.close();
		}
	}

	private static void publish(SailSource source, Statement statement) throws Exception {
		try (SailSink sink = source.sink(IsolationLevels.NONE)) {
			sink.prepare();
			sink.approve(statement);
			sink.flush();
		}
	}

	private static void write(SailSource source, String value) throws Exception {
		try (SailSink sink = source.sink(IsolationLevels.NONE)) {
			sink.approve(statement(value));
			sink.flush();
		}
	}

	private static boolean contains(SailSource source, Statement statement) throws Exception {
		try (SailDataset dataset = source.dataset(IsolationLevels.NONE);
				CloseableIteration<? extends Statement> statements = dataset.getStatements(statement.getSubject(),
						statement.getPredicate(), statement.getObject(), statement.getContext())) {
			return statements.hasNext();
		}
	}

	private static Statement statement(String value) {
		Resource subject = VALUE_FACTORY.createIRI("urn:memory:frozen:" + value);
		IRI predicate = VALUE_FACTORY.createIRI("urn:memory:frozen:predicate");
		Value object = VALUE_FACTORY.createLiteral(value);
		return VALUE_FACTORY.createStatement(subject, predicate, object);
	}
